    "operation": "baseline-upgrade-apply",
    "mintedByStepKind": "mutation",
    "requestClass": "mutation",
    "note": "RENAME. The command runs `analysis` then `mutation`; the operation names the APPLY half, because the analysis half mints a Run and no mutation."
   },
   "core-repair": {
    "operation": "core-repair",
    "mintedByStepKind": "mutation",
    "requestClass": "lifecycle"
