    "operation": "waiver-change",
    "mintedByStepKind": "mutation",
    "requestClass": "mutation",
    "note": "RENAME. `waive` adds a waiver; the operation is the effect class `waiver-change`, which also covers the amendment and revocation this same command performs."
   }
  },
  "admissibleGenericFieldDomain": {
   "fields": [
    "invocation-record.schema.json#/$defs/MutationParams/properties/mutationClass",
    "invocation-record.schema.json#/$defs/MutationReplayScopeV1/properties/operation"
   ],
   "operations": [
    "baseline-adopt",
    "baseline-export",
    "baseline-upgrade-apply",
    "config-write",
    "core-repair",
    "core-rollback",
    "core-update",
    "import",
