def walk(x,y,p):
    if type(x)!=type(y): print('TYPE',p); return
    if isinstance(x,dict):
        for k in sorted(set(x)|set(y)):
            if k not in x: print('ADDED',p+'/'+k, json.dumps(y[k])[:300])
            elif k not in y: print('REMOVED',p+'/'+k)
            else: walk(x[k],y[k],p+'/'+k)
    elif isinstance(x,list):
        if x!=y: print('LIST',p, json.dumps(x)[:200], '->', json.dumps(y)[:200])
    elif x!=y:
        s1,s2=str(x),str(y)
        print('VALUE',p, s1[:160], '->', s2[:400])
for k in ('RecipeRef','FileEdit','EvidenceRequirement','RepairPlanDescriptor','RepairPlanV1'): walk(a[k],b[k],k)
c3=[json.load(open(f)) for f in [S+'evaluator3/common.schema.json']][0]['\$defs']
c1=json.load(open(S+'common.schema.json'))['\$defs']
for k in ('RunId','PlanId','SnapshotId','ProjectId','RepairPlanId'): print(k, json.dumps(c1.get(k)), '|', json.dumps(c3.get(k)))
"

