import json
D='/private/tmp/opensip-design-corrections/claude-workflow-owner-completion.v1/work/source/docs/coop/design-corrections/workflows/schemas/'
env=json.load(open(D+'evaluator3/command-envelope.schema.json'))
print(json.dumps(env['\$defs']['PolicyTestResultRecordV1'], indent=2))
pd=json.load(open(D+'policy-document.schema.json'))
names=set(); seen=set()
def walk(node):
    if isinstance(node, dict):
        r=node.get('\$ref')
        if isinstance(r,str) and r.startswith('#/\$defs/'):
            k=r.split('/')[-1]
            if k not in seen: seen.add(k); walk(pd['\$defs'][k])
        for key,v in node.items():
            if key=='properties' and isinstance(v,dict): names.update(v)
            walk(v)
    elif isinstance(node,list):
        for v in node: walk(v)
seen.add('PolicyDocumentV1'); walk(pd['\$defs']['PolicyDocumentV1'])
print('reachable defs', sorted(seen)); print('names', sorted(names))
print([k for k in ('hook','script','exec','include','expression') if k in names])
"

